-- The five master calendar days, as the one source every view reads.
--
-- Wednesday September 30 to Sunday October 4, 2026. Rows that already existed
-- keep their id and their guest copy, so menus and activity detail survive the
-- import; rows the master supersedes are copied into schedule_items_archive
-- before they leave the working views, so nothing is lost.
--
-- Every row carries its lead, assigned team, what happens, setup notes, and
-- whether it is Program or Operations. The run of show, the volunteer duties, a
-- person's own schedule and the guest schedule are then four readings of the
-- same records rather than three copies that drift apart.
--
-- Volunteer duties are the Operations rows, one task each, linked back to the
-- row it came from. Pre-event tasks are left exactly as they are.

create table if not exists public.schedule_items_archive (
  id uuid primary key,
  engagement_id uuid not null references public.engagements (id) on delete cascade,
  snapshot jsonb not null,
  archived_at timestamptz not null default now()
);

alter table public.schedule_items_archive enable row level security;

drop policy if exists schedule_items_archive_select_staff on public.schedule_items_archive;
create policy schedule_items_archive_select_staff
  on public.schedule_items_archive for select
  using (public.is_platform_staff());

revoke all on public.schedule_items_archive from anon;

