  ('a1082a68-a431-56fc-b48b-a60ff875c0b4'::uuid, $q$sun$q$, $q$9:30 am$q$, $q$10:00 pm$q$, $q$Final property walkthrough and team departure$q$, $q$Operations$q$, $q$planner$q$, $q$morning$q$, null::jsonb, $q${"purpose": "Check every room, gather lost-and-found, confirm nothing remains, and pray.", "owner": "Brooke and Ryan", "support": "Remaining team", "category": "operations", "materials": "Master checklist, keys", "notes": "The source times this 9:30 AM to 10:00 PM, while the surrounding rows are morning.", "confirm": "time"}$q$::jsonb, 76, true);

select count(*) into expected from master;
if expected <> 77 then
  raise exception 'master: expected 77 rows, got %', expected;
end if;

/* Keep a copy of everything the master does not name, then retire it from the
   working views in one step so no stale row or assignment is left behind. */
insert into public.schedule_items_archive (id, engagement_id, snapshot)
select s.id, s.engagement_id, to_jsonb(s)
  from public.schedule_items s
 where s.engagement_id = shine
   and s.id not in (select id from master)
on conflict (id) do nothing;

delete from public.tasks
 where engagement_id = shine
   and schedule_item_id is not null
   and schedule_item_id not in (select id from master);

delete from public.schedule_item_ops
 where engagement_id = shine
   and schedule_item_id not in (select id from master);

delete from public.schedule_items
 where engagement_id = shine
   and id not in (select id from master);

insert into public.schedule_items
  (id, engagement_id, day_key, starts_label, ends_label, title, track,
   audience, daypart, status, guest_guide, position)
select m.id, shine, m.day_key, m.starts_label, m.ends_label, m.title, m.track,
       m.audience, m.daypart, 'confirmed', m.guest_guide, m.position
  from master m
on conflict (id) do update
   set day_key = excluded.day_key,
       starts_label = excluded.starts_label,
       ends_label = excluded.ends_label,
       title = excluded.title,
       track = excluded.track,
       audience = excluded.audience,
       daypart = excluded.daypart,
       status = 'confirmed',
       guest_guide = excluded.guest_guide,
       position = excluded.position;

select count(*) into found from public.schedule_items where engagement_id = shine;
if found <> expected then
  raise exception 'schedule: expected % rows, found %', expected, found;
end if;

insert into public.schedule_item_ops (schedule_item_id, engagement_id, detail)
select m.id, shine, m.ops from master m
on conflict (schedule_item_id) do update
   set detail = excluded.detail, updated_at = now();

/* Day-of duties are regenerated from the master. Pre-event tasks, which the
   master does not describe, are untouched. Nothing is marked done. */
delete from public.tasks
 where engagement_id = shine
   and coalesce(duty->>'phase', '') <> 'before';

insert into public.tasks
  (engagement_id, title, status, owner_name, schedule_item_id, duty)
select shine, m.title, 'todo', m.ops->>'owner', m.id,
       jsonb_build_object('phase', m.day_key, 'order', m.position,
                          'when', m.starts_label, 'fromMaster', true)
  from master m
 where m.is_duty;

select count(*) into found from public.tasks
 where engagement_id = shine and coalesce(duty->>'phase', '') = 'before';
if found < 14 then
  raise exception 'pre-event tasks: expected at least 14, found %', found;
end if;

if exists (select 1 from public.schedule_items
            where engagement_id = shine and title ~* 'wanyoni(?!yi)') then
  raise exception 'a misspelling remains';
end if;

end $migration$;
